sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;

	c.open = function(sysId , page , table){
		url = '?id=' + page + '&table=' + table + '&sys_id=' + sysId;
		window.open(url , '_current');
	}
};

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */

	var gr = new GlideRecord('x_1912290_techno_0_invoice');
	gr.addQuery('user',gs.getUserID());
	gr.addEncodedQuery("amount>javascript:global.getCurrencyFilter('x_1912290_techno_0_invoice','amount', 'USD;0')");
	gr.query();

	data.invoice = [];

	while(gr.next()){
		var json = {};
		json.contract = gr.contract.getDisplayValue();
		json.amount = gr.amount.getDisplayValue();
		json.sys = gr.getUniqueValue();
		json.number = gr.number.getDisplayValue();

		data.invoice.push(json);
	}
})();
